{"files": 
[{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "沈砺",
      "role": "protagonist",
      "identity": "精神病院患者/观察实验执行者",
      "traits": ["偏执", "控制欲强", "超忆症", "病态浪漫"],
      "overt_motivation": "完成观察实验，验证'纯粹爱情'理论",
      "covert_motivation": "渴望被真正理解，即使是通过病态的方式",
      "secret_fear": "被遗忘，失去对一切的控制",
      "misperception_of_other": "以为女主只是被动的实验对象，不知道她也在暗中观察他",
      "hidden_connection": "两人都是自愿进入实验的，他比她早来三个月"
    },
    {
      "name": "林晚",
      "role": "deuteragonist",
      "identity": "精神病院患者/观察实验对象",
      "traits": ["敏感", "坚韧", "失忆症", "自我毁灭倾向"],
      "overt_motivation": "配合治疗，找回记忆",
      "covert_motivation": "渴望被真正看见，即使代价是沉沦",
      "secret_fear": "永远无法逃离这个循环，被彻底遗忘",
      "misperception_of_other": "以为沈砺只是冷酷的实验执行者，不知道他也深陷其中",
      "hidden_connection": "她选择失忆是为了逃避过去的创伤，他选择超忆是为了记住一切"
    }
  ],
  "supporting_characters": [
    {
      "name": "陈默",
      "function": "反转点",
      "identity": "主治医生/实验观察者",
      "description": "冷漠的观察者，负责记录实验数据，在关键时刻揭示实验真相"
    }
  ],
  "relationship_dynamics": "沈砺与林晚是彼此的囚徒和狱卒——他操控她的记忆，她依赖他的追求；他以为自己是猎人，其实也是猎物；她以为自己是受害者，最终选择自愿沉沦。两人在规则怪谈般的每日重置中相爱相杀，清醒地看着彼此毁灭却无法停止。"
}"}, {"path": "outline.json", "content": "{
  "act_one": {
    "description": "建立世界观：精神病院每日重置规则，引入沈砺与林晚的核心关系，病历本作为规则载体首次出现",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "第47次清晨",
        "core_event": "林晚在第47次记忆重置后醒来，沈砺准时出现开始追求，病历本记录着'第47天'",
        "emotional_tone": "压抑的熟悉感",
        "key_scenes": ["林晚在白色病房醒来", "沈砺端着药瓶出现", "病历本上的日期记录", "第一次身体接触：他喂她吃药"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "墙上的刻痕",
        "core_event": "林晚发现沈砺在墙上刻满'今天她笑了几次'，开始怀疑这个地方的真实性",
        "emotional_tone": "悬疑与不安",
        "key_scenes": ["林晚独自探索病房", "发现墙上的刻痕", "沈砺发现后的反应", "药瓶作为每日仪式的强化"]
      }
    ],
    "turning_point": "林晚发现病历本上自己的签名日期是连续的——她没有失忆，是有人让她相信她失忆了"
  },
  "act_two": {
    "description": "冲突升级：林晚开始暗中调查，拼凑真相，沈砺的追求变得更加急切，双向暗恋在谎言中滋长",
    "key_chapters": [
      {
        "chapter_number": 3,
        "chapter_title": "记忆的裂缝",
        "core_event": "林晚开始假装失忆，暗中记录沈砺的行为模式，发现他也在'表演'",
        "emotional_tone": "紧张的博弈",
        "key_scenes": ["林晚藏起一片药", "在病历本背面记录真相", "沈砺的追求台词重复", "两人对视时的微妙变化"]
      },
      {
        "chapter_number": 4,
        "chapter_title": "陈医生的档案",
        "core_event": "林晚偷看到实验档案，发现自己和沈砺都是自愿签署协议的，'互相治疗'是谎言",
        "emotional_tone": "绝望的觉醒",
        "key_scenes": ["林晚潜入医生办公室", "阅读实验协议", "发现沈砺的签名在她之前", "陈默医生的冷漠旁白"]
      },
      {
        "chapter_number": 5,
        "chapter_title": "第48天的异常",
        "core_event": "林晚的记忆没有重置，她记得前一天的一切，沈砺发现后陷入恐慌",
        "emotional_tone": "崩溃边缘",
        "key_scenes": ["清晨林晚记得沈砺昨天说的话", "沈砺的恐慌反应", "墙上的刻痕新增一行", "药瓶被摔碎"]
      }
    ],
    "turning_point": "沈砺向林晚坦白：'只有疯子的爱情才纯粹'，他故意让她依赖，因为这是唯一能证明爱情存在的方式"
  },
  "act_three": {
    "description": "高潮与结局：X-Y化学反应爆发，林晚面临选择——逃离或留下，最终选择清醒地沉沦",
    "key_chapters": [
      {
        "chapter_number": 6,
        "chapter_title": "囚徒的抉择",
        "core_event": "林晚与沈砺对峙，她有机会离开，但选择留下，说'那你明天记得再追我一次'",
        "emotional_tone": "病态的平静",
        "key_scenes": ["陈默医生给出离开的机会", "林晚看向沈砺", "沈砺墙上的刻痕特写", "林晚的最终选择"]
      },
      {
        "chapter_number": 7,
        "chapter_title": "第49次清晨",
        "core_event": "林晚假装记忆重置，沈砺知道她在演戏，但配合她继续这场游戏，两人成为彼此的共犯",
        "emotional_tone": "绝望的温柔",
        "key_scenes": ["林晚假装不认识沈砺", "沈砺眼底的痛苦与释然", "病历本新增一页：'她选择了'", "药瓶重新装满，仪式继续"]
      }
    ],
    "turning_point": ""
  }
}"}]

}

